const config = $('Configurar execução manual').first().json;
const cases = [
  {case_id:'dengue-compensa', label:'Dengue — Compensa', media_title:'Unidades registram aumento de atendimentos por dengue na Compensa', media_text:'Serviços de saúde da zona oeste observaram crescimento na procura por atendimento de pessoas com febre, dor no corpo e sinais de sangramento na Compensa.', community_text:'Moradores da Compensa comentam que várias famílias procuraram atendimento nos últimos dias por febre alta, dores no corpo e mal-estar.'},
  {case_id:'sarampo-cidade-nova', label:'Sarampo — Cidade Nova', media_title:'Crianças com febre e manchas na pele mobilizam atendimento na Cidade Nova', media_text:'Famílias buscaram avaliação para crianças com febre e manchas avermelhadas na pele em diferentes pontos da Cidade Nova.', community_text:'Responsáveis relatam em grupos do bairro crianças com febre, olhos irritados e manchas vermelhas pelo corpo ao longo desta semana.'},
  {case_id:'leptospirose-jorge-teixeira', label:'Leptospirose — Jorge Teixeira', media_title:'Após alagamentos, moradores procuram atendimento com sintomas febris', media_text:'Unidades atenderam pessoas com febre, dor muscular e náusea depois do contato com água acumulada durante as chuvas.', community_text:'No Jorge Teixeira, moradores relatam febre forte e dores nas pernas depois de atravessarem áreas alagadas para chegar em casa.'},
  {case_id:'malaria-taruma', label:'Malária — Tarumã', media_title:'Casos de febre com calafrios levam moradores do Tarumã às unidades de saúde', media_text:'Equipes registraram procura de moradores do Tarumã com episódios de febre que vai e volta, calafrios intensos e sudorese, principalmente no fim do dia.', community_text:'Moradores próximos a áreas de mata no Tarumã relatam vizinhos com febre em ciclos, tremores e suor intenso durante a noite.'},
  {case_id:'doenca-diarreica-educandos', label:'Doença diarreica — Educandos', media_title:'Aumenta procura por atendimento após episódios de diarreia em Educandos', media_text:'Moradores de Educandos buscaram atendimento com diarreia, vômito e dor abdominal. Os relatos se concentram em famílias de ruas próximas à orla.', community_text:'Famílias de Educandos dizem que adultos e crianças da mesma casa tiveram diarreia e vômitos depois do fim de semana.'},
  {case_id:'influenza-parque-dez', label:'Síndrome gripal — Parque 10', media_title:'Síndrome gripal eleva ausências em escolas do Parque 10', media_text:'Escolas do Parque 10 registraram aumento de faltas entre alunos com febre, tosse e dor de garganta durante a semana.', community_text:'Responsáveis de alunos do Parque 10 relatam muitas crianças em casa com tosse forte, febre e incômodo na garganta.'},
  {case_id:'hepatite-a-colonia-antonio-aleixo', label:'Hepatite A — Colônia Antônio Aleixo', media_title:'Pacientes com sinais de icterícia são atendidos na Colônia Antônio Aleixo', media_text:'Serviços locais avaliaram pacientes com pele e olhos amarelados, náusea e dor abdominal na Colônia Antônio Aleixo.', community_text:'Moradores da Colônia Antônio Aleixo comentam casos de pessoas com olhos amarelados, enjoo persistente e dor na barriga.'},
  {case_id:'chikungunya-ponta-negra', label:'Chikungunya — Ponta Negra', media_title:'Dor intensa nas articulações motiva atendimentos na Ponta Negra', media_text:'Pacientes da Ponta Negra procuraram atendimento com febre, inchaço e dores fortes nas articulações, com dificuldade para caminhar.', community_text:'Em grupos da Ponta Negra, moradores relatam febre seguida de dor muito forte nas mãos, pés e joelhos.'},
  {case_id:'meningite-zumbi', label:'Síndrome meníngea — Zumbi', media_title:'Pacientes com febre e rigidez de nuca são avaliados na zona leste', media_text:'Uma unidade da zona leste recebeu pacientes do Zumbi com febre alta, dor de cabeça intensa e dificuldade para movimentar o pescoço.', community_text:'Moradores do Zumbi relatam pessoas da mesma área com febre, dor de cabeça muito forte e pescoço endurecido.'},
  {case_id:'febre-amarela-reserva-ducke', label:'Síndrome compatível com febre amarela — Reserva Ducke', media_title:'Quadros febris após atividades em área de mata são investigados em Manaus', media_text:'Pessoas que estiveram no entorno da Reserva Ducke foram atendidas com febre, dor muscular e coloração amarelada nos olhos.', community_text:'Moradores próximos à Reserva Ducke relatam trabalhadores com febre forte, dores no corpo e olhos amarelados depois de entrarem na mata.'}
];
if (!['single','batch'].includes(config.execution_scope)) throw new Error('execution_scope deve ser single ou batch');
if (!['offline','online'].includes(config.mode)) throw new Error('mode deve ser offline ou online');
const selected = config.execution_scope === 'batch' ? cases : cases.filter(item => item.case_id === config.case_id);
if (selected.length === 0) throw new Error('case_id não pertence ao catálogo permitido');
return selected.map((item, index) => ({json:{...item, mode:config.mode, synthetic:true, sequence:index + 1, total:selected.length}}));
